update sc_plans set spec=jsonb_set(spec,'{shots}',coalesce(spec->'shots','[]'::jsonb) || $q$[{"n": 1, "id": "hw1_chestnut", "vid": "hwv1_chestnut", "img_prompt": "GRANDMA: a small Korean grandma in her late seventies, silver hair in a low bun, round kind face with smile wrinkles, plum-purple quilted vest over a cream blouse, dark grey long skirt. PLACE: a small old hanok house at the end of a narrow Seoul alley: grey-tiled roof with gently curved eaves, a weathered wooden double gate, a low grey stone wall, a single stone step in front of the gate. Golden autumn afternoon. The grandma sits on the stone step in front of her wooden gate with a shallow round wicker basket of roasted chestnuts on her lap and places one roasted chestnut on the top of the low stone wall; Kachi hops along the wall toward the chestnut. Her hands are mostly hidden behind the basket. Ginkgo leaves on the ground. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg"], "reuse": null, "action": "Kachi takes one small hop toward the chestnut on the wall and tilts its head happily; the grandma smiles softly.", "dur": 5, "cap": "Every day, one chestnut for Kachi.", "detail": "밤 바구니·담 위 밤 한 톨 (까치와 할머니의 매일)"}, {"n": 2, "id": "hw2_alone", "vid": "hwv2_alone", "img_prompt": "GRANDMA: a small Korean grandma in her late seventies, silver hair in a low bun, round kind face with smile wrinkles, plum-purple quilted vest over a cream blouse, dark grey long skirt. PLACE: a small old hanok house at the end of a narrow Seoul alley: grey-tiled roof with gently curved eaves, a weathered wooden double gate, a low grey stone wall, a single stone step in front of the gate. Halloween night. The grandma sits alone on the stone step of her dark gate with the basket of roasted chestnuts on her lap, looking down the alley with a lonely little smile. Down the alley the neighbors' gates glow with orange carved pumpkin lanterns with cute smiling faces, but her gate has no lantern. On the inside wall behind the open gate hangs a small wooden frame holding a child's crayon drawing: a grandma with a bun and a small boy in a yellow beanie holding hands under a big red heart (simple drawing, no writing). Kachi sits small on the edge of her roof eave above her, looking down at her. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg", "social/side/gen/hw1_chestnut.jpeg"], "reuse": null, "action": "The grandma slowly lowers her gaze to the basket on her lap; far down the alley the pumpkin lanterns flicker softly; Kachi on the eave tilts its head.", "dur": 5, "cap": "Halloween night. No one knocked.", "detail": "어두운 할머니 대문 ↔ 이웃 대문의 호박등, 대문 안 액자 속 크레용 그림(할머니+노란 비니 꼬마)"}]$q$::jsonb) where id='P261031-halloween-gotgam'